<?php require '../common.php';startpage('Bus Admin Panel');nav('<a href="index.php">Search</a><a href="bookings.php">Bookings/report</a>');$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$n=$_POST['bus_name'];$c=$_POST['category'];$f=$_POST['origin'];$t=$_POST['destination'];$d=$_POST['travel_date'];$time=$_POST['departure_time'];$p=(float)$_POST['price'];$seats=max(1,(int)$_POST['seats']);$s=$conn->prepare('INSERT INTO buses(bus_name,category,origin,destination,travel_date,departure_time,price,total_seats,available_seats) VALUES(?,?,?,?,?,?,?,?,?)');$s->bind_param('ssssssdii',$n,$c,$f,$t,$d,$time,$p,$seats,$seats);$s->execute();$msg='Bus added.';}if($msg)echo '<p class="msg">'.e($msg).'</p>';?><form method="post"><h2>Add bus</h2><input name="bus_name" placeholder="Bus name" required><select name="category"><option>Volvo</option><option>Sleeper coach</option><option>Coach</option></select><input name="origin" placeholder="From" required><input name="destination" placeholder="To" required><input type="date" name="travel_date" required><input type="time" name="departure_time" required><input type="number" step=".01" name="price" placeholder="Price" required><input type="number" name="seats" value="40" min="1"><button>Add bus</button></form><table><tr><th>Bus</th><th>Category</th><th>Route</th><th>Seats</th></tr><?php $rs=$conn->query('SELECT * FROM buses');while($b=$rs->fetch_assoc()):?><tr><td><?=e($b['bus_name'])?></td><td><?=e($b['category'])?></td><td><?=e($b['origin'])?> → <?=e($b['destination'])?></td><td><?=$b['available_seats']?>/<?=$b['total_seats']?></td></tr><?php endwhile;?></table><?php endpage();?>